SELECT channel, DATE_TRUNC('MONTH', ends_on) AS activity_month, AVG(discount_pct) AS avg_discount_pct, SUM(CASE WHEN promo_code = 'VIP' THEN discount_pct ELSE 0 END) AS vip_discount_pct, APPROX_PERCENTILE(discount_pct, 0.9) AS discount_pct_p90, RANK() OVER (PARTITION BY channel ORDER BY AVG(discount_pct) DESC) AS avg_discount_pct_rank FROM promotions GROUP BY channel, activity_month ORDER BY channel DESC;
